  split_ifs <;> constructor <;> try {unitInterval.nonneg _, linarith [unitInterval.nonneg _, unitInterval.le_one _]};> apply mul_le_one₀ <;> try {unitInterval.nonneg _, linarith [_, _]));

/-- For any path `p` from `x₀` to `x₁`, we have a homotopy from the constant path based at `x₀` to
  `p.trans p.symm`. -/
def reflTransSymm (p : Path x₀ x₁) : Homotopy (Path.refl x₀) (p.trans p.symm)   := by
  intro x
  constructor
  simp [Pth_extend_mk_apply_iff]
  split_ifs with h;
  exact by simp [h, Pth_extend_mk_apply_iff];
  exact by simp [h, Pth_extend_mk_apply_iff, (not_le.1 h).le, zero_le_one];

